from src.hacker_rank.super_digit import get_super_digit
from tests.unit_test_template import UnitTestTemplate


class SuperDigitTest(UnitTestTemplate):
    def test_get_super_digit_single_digit(self):
        n = 9
        k = 1
        expected = 9
        actual = get_super_digit(n, k)
        self.assertEqual(expected, actual)

    def test_get_super_digit(self):
        n = 9875
        k = 4
        expected = 8
        actual = get_super_digit(n, k)
        self.assertEqual(expected, actual)

    def test_get_super_digit_large(self):
        n = int('', 16)
        k = 100000
        expected = 7
        actual = get_super_digit(n, k)
        self.assertEqual(expected, actual)
